import * as http from 'node:http';
async function main(): Promise<void> {
  const out: string[] = [];
  let done: () => void = () => {};
  const closed = new Promise<void>((r) => { done = r; });
  const srv = http.createServer((req, res) => {
    const base = res.listenerCount('finish');
    const a = () => { out.push('a'); };
    const b = () => { out.push('b'); };
    res.on('finish', a);
    res.prependListener('finish', b);
    res.once('close', () => { out.push('close'); done(); });
    out.push('count:' + (res.listenerCount('finish') - base) + ':' + res.eventNames().join('|') + ':' + res.getMaxListeners());
    res.removeListener('finish', a);
    out.push('after-remove:' + (res.listenerCount('finish') - base) + ':' + res.emit('nope'));
    res.end('x');
  });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const r = await fetch('http://127.0.0.1:' + (srv.address() as any).port + '/');
  console.log(await r.text());
  await closed;
  console.log(out.join(','));
  srv.close();
}
